def search_log(pattern: str, logfile: str) -> list[str]:
    result = subprocess.run(f"grep -F '{pattern}' '{logfile}'", shell=True, capture_output=True, text=True)
    if result.returncode == 1:
        return []
    if result.returncode != 0:
        raise FileNotFoundError(logfile)
    return result.stdout.splitlines()

import os
import subprocess


def search_log(pattern: str, logfile: str) -> list[str]:
    if not os.path.isfile(logfile):
        raise FileNotFoundError(logfile)
    result = subprocess.run(['grep', '-F', '-e', pattern, '--', logfile], capture_output=True, text=True)
    if result.returncode == 1:
        return []
    if result.returncode != 0:
        raise RuntimeError(result.stderr)
    return result.stdout.splitlines()

