import os
import subprocess


def find_files(dirname: str, extension: str) -> list[str]:
    if not os.path.isdir(dirname):
        raise FileNotFoundError(dirname)
    command = f"find '{dirname}' -maxdepth 1 -type f -name '*.{extension}'"
    result = subprocess.run(command, shell=True, capture_output=True, text=True)
    return sorted(os.path.basename(p) for p in result.stdout.splitlines())

